#!/usr/bin/env node
/* SUITE: security — 安全矩阵
 *
 * 覆盖 case：
 *  1. scope 越权：recv Key 上报→403；send Key 连 /v1/stream→403/拒
 *  2. Key 篡改：改字符→401；改前缀→401
 *  3. 无 Authorization 头→401；非 Bearer scheme（Basic）→401
 *  4. 未登录访问 /v1/devices /v1/keys /v1/notifications→各 401
 *  5. Key 哈希不可逆：DB 中 key_hash 为 argon2id PHC 格式（$argon2id$ 开头），
 *     不等于明文、DB 文件二进制中搜不到明文 Key
 *  6. 会话 Cookie 属性：Set-Cookie 含 HttpOnly
 *  7. SQL 注入：恶意 username/输入 → 不报错、不越权、正常 400/404
 *  8. 路径穿越：/../etc/passwd、/%2e%2e/ → 不读出站外文件（403/404/400）
 */
import { readFileSync } from "node:fs";
import * as H from "../lib/harness.mjs";

async function main() {
	console.log("=== SUITE: security（安全矩阵）===");
	const server = await H.startServer({ rpId: "localhost" });
	const { sendKey, recvKey, session } = H.seed(server.dbPath, "sectest");

	// ---- 1. scope 越权 ----
	H.eq("recv Key 上报 → 403",
		(await H.req(server.base, "/v1/notify", { key: recvKey, body: { title: "t", status: "success" } })).status, 403);
	// send Key 连 WS（无 receive scope）。WS 升级请求用普通 HTTP 发，非 101 即被正确拒绝
	const wsResp = await H.req(server.base, "/v1/stream", { key: sendKey, headers: { Connection: "Upgrade", Upgrade: "websocket" } });
	H.check("send Key 连 /v1/stream 被拒(非101)", wsResp.status !== 101, `got ${wsResp.status}`);

	// ---- 2. Key 篡改 ----
	const tampered = sendKey.slice(0, -4) + (sendKey.endsWith("aaaa") ? "bbbb" : "aaaa");
	H.eq("篡改尾部的 Key → 401",
		(await H.req(server.base, "/v1/notify", { key: tampered, body: { title: "t", status: "success" } })).status, 401);
	const prefixChanged = sendKey.replace("ant_send_", "ant_live_");
	H.eq("改前缀的 Key → 401",
		(await H.req(server.base, "/v1/notify", { key: prefixChanged, body: { title: "t", status: "success" } })).status, 401);

	// ---- 3. 鉴权头缺失/错误 scheme ----
	H.eq("无 Authorization 头 → 401",
		(await H.req(server.base, "/v1/notify", { body: { title: "t", status: "success" } })).status, 401);
	H.eq("Basic scheme → 401",
		(await H.req(server.base, "/v1/notify", { headers: { Authorization: "Basic " + sendKey }, body: { title: "t", status: "success" } })).status, 401);

	// ---- 4. 未登录访问受保护端点 ----
	for (const p of ["/v1/devices", "/v1/keys", "/v1/notifications"]) {
		H.eq(`未登录 GET ${p} → 401`, (await H.req(server.base, p)).status, 401);
	}

	// ---- 5. Key 哈希不可逆 ----
	// 5a. DB 二进制中搜不到明文 Key
	const dbBuf = readFileSync(server.dbPath);
	H.check("DB 文件不含明文 Key", !dbBuf.includes(sendKey), "明文 Key 出现在 DB 文件中");
	H.check("DB 文件不含明文 recv Key", !dbBuf.includes(recvKey));
	// 5b. key_hash 是 argon2id PHC 格式（$argon2id$ 出现在 DB 中，且不等于明文）
	H.check("DB 含 argon2id 哈希标记", dbBuf.includes("$argon2id$"), "未找到 $argon2id$ PHC 标识");

	// ---- 6. 会话 Cookie HttpOnly ----
	// 触发一次 Set-Cookie：用 devseed 的 session 调 logout 会 ClearCookie（也带 HttpOnly）；
	// 更直接：注册流程会 Set-Cookie。这里用 logout 的 Set-Cookie 验证属性。
	const logoutResp = await fetch(server.base + "/v1/auth/logout", {
		method: "POST",
		headers: { Cookie: "anotify_session=" + session },
		redirect: "manual",
	});
	const setCookie = logoutResp.headers.get("set-cookie") || "";
	H.check("Set-Cookie 含 HttpOnly", /httponly/i.test(setCookie), `set-cookie: ${setCookie}`);
	H.check("Set-Cookie 指定 anotify_session", setCookie.includes("anotify_session"));

	// ---- 7. SQL 注入 ----
	// 恶意 username 注册 options（应正常处理，不报错不越权）
	const inj1 = await H.req(server.base, "/v1/auth/register/options", {
		body: { username: "admin' OR '1'='1", displayName: "x" },
	});
	H.check("SQL注入 username 注册 options 不 500", inj1.status !== 500, `got ${inj1.status}`);
	// 恶意输入到 notify title（注入串当普通文本）
	const inj2 = await H.req(server.base, "/v1/notify", {
		key: sendKey,
		body: { title: "'; DROP TABLE users;--", status: "success" },
	});
	H.eq("SQL注入串作为 title 上报仍正常", inj2.status, 200);
	// 注入后表仍在（会话还能用）
	H.eq("SQL注入后服务正常（会话可用）",
		(await H.req(server.base, "/v1/notifications", { session })).status, 200);
	// 恶意 session 值
	H.eq("伪造 session → 401",
		(await H.req(server.base, "/v1/notifications", { session: "sess_fake.' OR '1'='1" })).status, 401);

	// ---- 8. 路径穿越 ----
	for (const p of ["/../etc/passwd", "/%2e%2e/%2e%2e/etc/passwd", "/..%2f..%2fetc%2fpasswd", "/static/../../etc/passwd"]) {
		const r = await H.req(server.base, p);
		const leaked = r.text.includes("root:") || r.text.includes("/bin/bash");
		H.check(`路径穿越 ${p} 不泄露文件(${r.status})`, !leaked && r.status !== 200 || !leaked, `status=${r.status}`);
	}

	const passed = H.summary("security");
	server.stop();
	process.exit(passed ? 0 : 1);
}
main().catch((e) => { console.error(e); process.exit(1); });

