// send Key 连 WS（无 receive scope）→ 应在握手阶段被拒（连接失败/立即关闭，收不到 hello）
{
	const wsUrl = server.base.replace(/^http/, "ws") + "/v1/stream";
	const outcome = await new Promise((resolve) => {
		let settled = false;
		const done = (v) => { if (!settled) { settled = true; resolve(v); } };
		try {
			const ws = new WebSocket(wsUrl, { headers: { Authorization: "Bearer " + sendKey } });
			const timer = setTimeout(() => done("timeout-no-hello"), 3000);
			ws.onmessage = (ev) => {
				try {
					const f = JSON.parse(ev.data);
					if (f.type === "hello") { clearTimeout(timer); ws.close(); done("got-hello"); }
					else if (f.type === "error") { clearTimeout(timer); ws.close(); done("error-frame:" + (f.message || f.code || "")); }
				} catch { /* ignore */ }
			};
			ws.onerror = () => { clearTimeout(timer); done("conn-error"); };
			ws.onclose = (e) => { clearTimeout(timer); done("closed:" + e.code); };
		} catch (e) { done("thrown:" + e); }
	});
	H.check("send Key 连 /v1/stream 被拒（收不到 hello）", outcome !== "got-hello", `outcome=${outcome}`);
}

